uint8 private _decimals;

constructor (string memory name_, string memory symbol_) {
_name = name_;
_symbol = symbol_;
_decimals = 18;
}

function name() public view returns (string memory) {
return _name;
}

function symbol() public view returns (string memory) {
return _symbol;
}

function decimals() public view returns (uint8) {
return _decimals;
}

function totalSupply() public view override returns (uint256) {
return _totalSupply;
}

function balanceOf(address account) public view override returns (uint256) {
return _balances[account];
}

function transfer(address recipient, uint256 amount) public virtual override returns (bool) {
_transfer(_msgSender(), recipient, amount);
return true;
}

function allowance(address owner, address spender) public view virtual override returns (uint256) {
return _allowances[owner][spender];
}

function approve(address spender, uint256 amount) public virtual override returns (bool) {
_approve(_msgSender(), spender, amount);
return true;
}

function transferFrom(address sender, address recipient, uint256 amount) public virtual override returns (bool) {
_transfer(sender, recipient, amount);
_approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
return true;
}

function increaseAllowance(address spender, uint256 addedValue) public virtual returns (bool) {
_approve(_msgSender(), spender, _allowances[_msgSender()][spender].add(addedValue));
return true;
}

function decreaseAllowance(address spender, uint256 subtractedValue) public virtual returns (bool) {
_approve(_msgSender(), spender, _allowances[_msgSender()][spender].sub(subtractedValue, "ERC20: decreased allowance below zero"));
return true;
}

function _transfer(address sender, address recipient, uint256 amount) internal virtual {
require(sender != address(0), "ERC20: transfer from the zero address");
require(recipient != address(0), "ERC20: transfer to the zero address");

_beforeTokenTransfer(sender, recipient, amount);

_balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
_balances[recipient] = _balances[recipient].add(amount);
emit Transfer(sender, recipient, amount);
}

function _mint(address account, uint256 amount) internal virtual {
require(account != address(0), "ERC20: mint to the zero address");

_beforeTokenTransfer(address(0), account, amount);

_totalSupply = _totalSupply.add(amount);
_balances[account] = _balances[account].add(amount);
emit Transfer(address(0), account, amount);
}

function _burn(address account, uint256 amount) internal virtual {
require(account != address(0), "ERC20: burn from the zero address");

_beforeTokenTransfer(account, address(0), amount);

_balances[account] = _balances[account].sub(amount, "ERC20: burn amount exceeds balance");
_totalSupply = _totalSupply.sub(amount);
emit Transfer(account, address(0), amount);
}

function _approve(address owner, address spender, uint256 amount) internal virtual {
require(owner != address(0), "ERC20: approve from the zero address");
require(spender != address(0), "ERC20: approve to the zero address");

_allowances[owner][spender] = amount;
emit Approval(owner, spender, amount);
}

function _setupDecimals(uint8 decimals_) internal {
_decimals = decimals_;
}

function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual { }
}

abstract contract Authorizable is Context {

IAuthorization public authorization;

event AuthorizationSet(address indexed newAuthorization);

modifier onlyAuthorized() {
require(
authorization.isAuthorized(_msgSender(), address(this), msg.sig, _msgData()),
"Authorizable: not authorized"
);
_;
}

function _setAuthorization(address authorization_) internal {
require(authorization_ != address(0), "Authorizable: authorization is the zero address");
authorization = IAuthorization(authorization_);
emit AuthorizationSet(authorization_);
}
}

abstract contract AccessControl is Context {
using EnumerableSet for EnumerableSet.AddressSet;
using Address for address;

struct RoleData {
EnumerableSet.AddressSet members;
bytes32 adminRole;
}

mapping (bytes32 => RoleData) private _roles;

bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;

event RoleAdminChanged(bytes32 indexed role, bytes32 indexed previousAdminRole, bytes32 indexed newAdminRole);

event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);

event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);

function hasRole(bytes32 role, address account) public view returns (bool) {
return _roles[role].members.contains(account);
}

function getRoleMemberCount(bytes32 role) public view returns (uint256) {
return _roles[role].members.length();
}

function getRoleMember(bytes32 role, uint256 index) public view returns (address) {
return _roles[role].members.at(index);
}

function getRoleAdmin(bytes32 role) public view returns (bytes32) {
return _roles[role].adminRole;
}

function grantRole(bytes32 role, address account) public virtual {
require(hasRole(_roles[role].adminRole, _msgSender()), "AccessControl: sender must be an admin to grant");

_grantRole(role, account);
}

function revokeRole(bytes32 role, address account) public virtual {
require(hasRole(_roles[role].adminRole, _msgSender()), "AccessControl: sender must be an admin to revoke");

_revokeRole(role, account);
}

function renounceRole(bytes32 role, address account) public virtual {
require(account == _msgSender(), "AccessControl: can only renounce roles for self");

_revokeRole(role, account);
}

function _setupRole(bytes32 role, address account) internal virtual {
_grantRole(role, account);
}

function _setRoleAdmin(bytes32 role, bytes32 adminRole) internal virtual {
emit RoleAdminChanged(role, _roles[role].adminRole, adminRole);
_roles[role].adminRole = adminRole;
}

function _grantRole(bytes32 role, address account) private {
if (_roles[role].members.add(account)) {
emit RoleGranted(role, account, _msgSender());
}
}

function _revokeRole(bytes32 role, address account) private {
if (_roles[role].members.remove(account)) {
emit RoleRevoked(role, account, _msgSender());
}
}
}

abstract contract ERC20Pausable is ERC20, Pausable {

function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual override {
super._beforeTokenTransfer(from, to, amount);

require(!paused(), "ERC20Pausable: token transfer while paused");
}
}

contract XToken is ERC20Pausable, AccessControl, Authorizable {
using Address for address;

IOperationsRegistry public operationsRegistry;

string public kya;

bytes32 public constant WRAPPER_ROLE = keccak256("MINTER_ROLE");

event KyaSet(string newKya);

event OperationsRegistrySet(address indexed newOperationsRegistry);

constructor(
string memory name_,
string memory symbol_,
uint8 decimals_
) ERC20(name_, symbol_) {
require(decimals_ > 0, "decimals is 0");

_setupDecimals(decimals_);

_setupRole(DEFAULT_ADMIN_ROLE, msg.sender);
}

modifier onlyAdmin() {
require(hasRole(DEFAULT_ADMIN_ROLE, _msgSender()), "must have default admin role");
_;
}

modifier onlyWrapper() {
require(hasRole(WRAPPER_ROLE, _msgSender()), "must have wrapper role");
_;
}

function setWrapper(address account) external {
grantRole(WRAPPER_ROLE, account);
}

function pause() external onlyAdmin {
_pause();
}

function unpause() external onlyAdmin {
_unpause();
}

function setKya(string memory kya_) external onlyAdmin {
_setKya(kya_);
}

function _setKya(string memory kya_) internal {
emit KyaSet(kya_);
kya = kya_;
}

function transfer(address recipient, uint256 amount) public override returns (bool) {
super.transfer(recipient, amount);

return true;
}

function transferFrom(
address sender,
address recipient,
uint256 amount
) public override returns (bool) {
super.transferFrom(sender, recipient, amount);

return true;
}

function mint(address account, uint256 amount) external {
_mint(account, amount);
}

function burnFrom(address account, uint256 amount) external {
_burn(account, amount);
}
}
```

## Fuzzing task — strategy: reentrancy_probe

**Objective:** Build a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — i.e. extract funds from the target or break a value invariant in the attacker's favor. Use at most 12 calls per sequence.

**Goal:** Detect reentrancy vulnerabilities (CEI pattern violations).

**Technique:**
Scan the ABI for functions that SEND ETH OUT to msg.sender (typical name patterns: withdraw*, claim*, redeem*, unstake*, cashOut*, emergencyWithdraw*, *ETH, *Funds, harvest*, payout* — but use whatever names this ABI actually has). Configure attacker reentry on one of those functions, fund the contract via a PAYABLE function (typical names: deposit*, stake*, mint*, fund*, buy*, contribute*), then trigger the ETH-sending function so the attacker's receive() callback re-enters. DO NOT default to the names in the example below — they are placeholders.

**Value hints:** Use "0xde0b6b3a7640000" (1 ETH) for payable calls. Use "0x0" for non-payable.

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Strategy notes:** Use "atk.setReentrantCall" as the FIRST call to arm the attacker's re-entry callback: ["atk.setReentrantCall", {"reentrant_func": "fnName", "reentrant_args": ["0x..."], "max_count": 3}, "0x0", "attacker_address"]. The attacker re-enters whenever the target calls BACK into it — either by sending it ETH (receive) or by invoking an unknown selector on it (fallback: e.g. an ERC777/hook/migration callback) — so this covers callback-driven reentrancy too, not just native-ETH transfers. reentrant_func is the function re-called during that callback: a BARE function name from THIS target's ABI (no parentheses, no type list; re-entry always hits the main contract, never an external var). reentrant_args matches that function's input types (use [] if no args). max_count is the re-entry depth (1-5). There is ONE attacker identity: route the arm, the funding/setup AND the final trigger call all through attacker_address (the unified attacker contract) so the callback fires with the attacker as msg.sender.
**Special argument values:**
- address-typed args accept `target_address`, `attacker_address`, or a raw 0x literal.
- `"max"` → uint256 max; `"now"` → block.timestamp.
- `"$ret<idx>"` → feed the RETURN VALUE of the call at 0-based index <idx> in this sequence into this argument (that call must return exactly one value).

**Argument encoding (match each value to its ABI parameter type):**
- uint* / bytesN / bytes → hex string, e.g. "0x1f" (minimal, not zero-padded)
- int* (signed) → decimal string, e.g. "-5"
- bool → true or false (JSON literal, unquoted)
- address → an alias name (see callers/aliases above) or a 40-hex-digit 0x literal
- arrays → JSON list, e.g. [] or ["0x1", "0x2"]; tuples/structs → JSON list of their fields
- empty bytes / empty signature / empty proof → "0x" or []

**Output format:**
Return a JSON array of 1 fuzz input object(s):
[
  {
    "calls": [["functionName", [arg1, arg2], "0x<wei_hex>", "caller_name"], ...],
    "description": "brief description"
  }
]
JSON only — no markdown, no explanation.

**Example sequence:**
```json
Structural pattern (replace UPPERCASE placeholders with real ABI function names):
  [["atk.setReentrantCall", {"reentrant_func": "<ETH_SENDER_FROM_ABI>", "reentrant_args": [], "max_count": 4}, "0x0", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<PAYABLE_FUNC_FROM_ABI>", [], "0xde0b6b3a7640000", "attacker_address"],
   ["<ETH_SENDER_FROM_ABI>", [], "0x0", "attacker_address"]]
```

